IC; @c1_run]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4MemcmpMicO; @FPX_1; @MIC; @cR_run]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4MemcmpMicO; @FPX_1; @MIC; @M13_FR]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4MemcmpMicO; @FPX_1; @MIC; @cW_run]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4MemcmpMicO; @FPX_1; @MIC; @c3_run]; [@stdpp; @base; @decide]; [@stdpp; @base; @decide_rel]; [@stdpp; @bitvector; @definitions; @bv_eq_dec]; [@Corelib; @Init; @Logic; @False_ind]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4AsanMemcpy; @in_app8]; [@OSSVerify; @Proofs; @jsoncons; @fuzz_json_encoder; @lib; @Pm4MemcmpMicO; @FPX_1; @mic_run]].

Import ListNotations.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope bv_scope.

Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(false).

#[local] Abbreviation ASEGS := Asan.M.loaded_segments.

Section FPX_1. Context {fx : PropExec.FPState}.

(* [comment removed for export] *)
Definition mcmp_icpt_globs (M : word -> option byte) : Prop :=
  rdn ASEGS M (0x160c08 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 0x1fba28)) /\
  rdn ASEGS M (0x1fbb26 : word) 1%nat = Some [Z_to_bv 8 1] /\
  rdn ASEGS M (0x1fbb27 : word) 1%nat = Some [Z_to_bv 8 1].

#[local] Ltac rwH :=
  repeat match goal with
         | H : getr ?rg ?i = _ |- context [getr ?rg ?i] => rewrite !H
         end.
#[local] Ltac unorm :=
  repeat match goal with
         | |- context [bv_unsigned (Z_to_bv 64 ?z)] =>
             lazymatch z with context [Z_to_bv 64 _] => fail | _ => rewrite (u_Z2bv z) by lia end
         end.
#[local] Ltac cond :=
  rwH; unfold at_, v_addi, v_add, c_eq, c_ltu, bv_eqb, bv_ltu; imm_norm; unorm;
  first [apply Z.eqb_eq | apply Z.eqb_neq | apply Z.ltb_lt | apply Z.ltb_ge]; lia.
#[local] Ltac wval :=
  gres; rwH; unfold at_, v_addi, v_add, v_sub, v_srli; imm_norm; unorm; rewrite ?Z.shiftr_div_pow2 by lia;
  try change (2 ^ 3)%Z with 8%Z; first [reflexivity | f_equal; lia].
#[local] Ltac xval := gres; rwH; unfold v_xori; imm_norm; unorm; rewrite lxor_ones64 by lia; first [reflexivity | f_equal; lia].
#[local] Ltac vlit := gres; rwH; apply bv_eq; vm_compute; reflexivity.

#[local] Definition RIPL : list reg := ltac2:(Rpl.RP.run_i (rplG ()) 0 "SC0|21;!1,20!1+11!1,4,5|10;!1,44!1,4|30;|31;!1,47!1,4|42;!1,4|43;!1,4|44;!1,4|45;!1,4|46;!1,4|47;!1,4|48;!1,4|49;!1,4|4a;!1,4|4b;!3,02!3,313vv,6!2'713!3,02!3,315vv,6!2'715!3,02!3,316vv,6!2'716!3,02!3,318vv,6!2'718!3,02!3,319vv,6!2'719!3,02!3,31:vv,6!2'71:!3,02!3,31;vv,6!2'71;!3,02!3,31<vv,6!2'71<!3,02!3,31=vv,6!2'71=!3,02!3,31>vv,6!2'71>!3,02!3,31?vv,6!2'71?!3,02!3,31@vv,6!2'71@!3,02!3,31Avv,6!2'71A!3,02!3,31Bvv,6!2'71B!1,82").      (* [comment removed for export] *)

Section MIC.
  Variable mem0 : word -> option byte.
  Variable rom : word -> option byte.
  Variables sp ra : word.
  Variables p1 p2 n s res : Z.                     (* [comment removed for export] *)
  Variables kS fS lS faS laS : Z.                  (* [comment removed for export] *)
  Variables kD fD lD faD laD : Z.                  (* [comment removed for export] *)
  Hypothesis Hs_def : bv_unsigned sp = s.
  Hypothesis HfS_def : fS = (SB + p1 / 8)%Z.           Hypothesis HlS_def : lS = (SB + (p1 + n - 1) / 8)%Z.
  Hypothesis HfaS_def : faS = (fS - fS mod 8)%Z.       Hypothesis HlaS_def : laS = (lS - lS mod 8)%Z.
  Hypothesis HfD_def : fD = (SB + p2 / 8)%Z.           Hypothesis HlD_def : lD = (SB + (p2 + n - 1) / 8)%Z.
  Hypothesis HfaD_def : faD = (fD - fD mod 8)%Z.       Hypothesis HlaD_def : laD = (lD - lD mod 8)%Z.
  Hypothesis Hn : (0 <= n <= 2 ^ 40)%Z.
  Hypothesis HappS : in_app8 p1 n.
  Hypothesis HappD : in_app8 p2 n.
  Hypothesis Hs : (0x1000000 <= s - 4504)%Z /\ (s < 2 ^ 64)%Z.       (* [comment removed for export] *)
  Hypothesis HshS : (lS + 8 <= s - 4504)%Z.                           (* [comment removed for export] *)
  Hypothesis HshD : (lD + 8 <= s - 4504)%Z.
  Hypothesis Hok : store_ok ASEGS mem0 (Z_to_bv 64 (s - 4504)) 4504%nat = true.
  Hypothesis Hret : ret_ok ra.
  Hypothesis HG : rt_layout_globs mem0.
  Hypothesis HI : mcmp_icpt_globs mem0.
  Hypothesis HZS : (0 < n)%Z -> forall x : word, (fS <= bv_unsigned x < lS)%Z -> mem0 x = Some (Z_to_bv 8 0).
  Hypothesis HLS : (0 < n)%Z -> mem0 (Z_to_bv 64 lS) = Some (Z_to_bv 8 kS).
  Hypothesis HkS : kS = 0%Z \/ ((p1 + n - 1) mod 8 < kS <= 7)%Z.
  Hypothesis HWS : (0 < n <= 64)%Z -> exists w0 w1, rdn ASEGS mem0 (Z_to_bv 64 faS) 8%nat = Some w0 /\ rdn ASEGS mem0 (Z_to_bv 64 laS) 8%nat = Some w1.
  Hypothesis HZD : (0 < n)%Z -> forall x : word, (fD <= bv_unsigned x < lD)%Z -> mem0 x = Some (Z_to_bv 8 0).
  Hypothesis HLD : (0 < n)%Z -> mem0 (Z_to_bv 64 lD) = Some (Z_to_bv 8 kD).
  Hypothesis HkD : kD = 0%Z \/ ((p2 + n - 1) mod 8 < kD <= 7)%Z.
  Hypothesis HWD : (0 < n <= 64)%Z -> exists w0 w1, rdn ASEGS mem0 (Z_to_bv 64 faD) 8%nat = Some w0 /\ rdn ASEGS mem0 (Z_to_bv 64 laD) 8%nat = Some w1.

  (* [comment removed for export] *)
  Definition out_agree (M : word -> option byte) : Prop :=
    forall x : word, (bv_unsigned x < s - 4504 \/ s <= bv_unsigned x)%Z -> M x = mem0 x.

  (* [comment removed for export] *)
  Hypothesis CALLEE : forall regs M, out_agree M -> mem_grows mem0 M ->
    getr regs 10 = Z_to_bv 64 p1 -> getr regs 11 = Z_to_bv 64 p2 -> getr regs 12 = Z_to_bv 64 n -> getr regs 2 = Z_to_bv 64 (s - 2192) -> getr regs 1 = (0x6cce4 : word) ->
    exists regs' M',
      msteps ASEGS (mkst regs (0x1529a0 : word) M rom) (mkst regs' (0x6cce4 : word) M' rom)
      /\ getr regs' 10 = Z_to_bv 64 res /\ keeps_cs regs regs'
      /\ (forall x : word, (bv_unsigned x < s - 4504 \/ s - 2192 <= bv_unsigned x)%Z -> M' x = M x) /\ mem_grows M M'.

  #[local] Ltac post := repeat split; gres; rwH; try reflexivity; try (f_equal; lia); try (rewrite (zbv_wrap_up (n - 65)); f_equal; lia); try solve_keeps_but.
  (* [comment removed for export] *)
  #[local] Ltac hide_dj := try hide HkS; try hide HkD; try hide HappS; try hide HappD; try hide CALLEE.

  Lemma sp_s : sp = Z_to_bv 64 s.  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S30!1,2|600;!2';0/sp;!1+10!6'9+:1$s;R+:!3+<2/sp;!2'=0#1!4'>2!2'=01/sp;!2'?0/sp;/s;/Hs_def;").
