  Definition qlR_inv (rg : bvmap 5 word) (i : Z) : Prop :=
    getr rg 11 = Z_to_bv 64 (fS + i) /\ getr rg 12 = Z_to_bv 64 lS /\ getr rg 13 = Z_to_bv 64 0 /\ getr rg 20 = Z_to_bv 64 p1 /\ getr rg 18 = Z_to_bv 64 p2 /\ getr rg 9 = Z_to_bv 64 n /\ getr rg 21 = Z_to_bv 64 0x1529a0 /\ getr rg 19 = ra /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 2 = Z_to_bv 64 (s - 2192) /\ getr rg 25 = Z_to_bv 64 (n - 65).
