  (* [comment removed for export] *)
  Definition cWqa_post (u0 u1 : Z) (rg : bvmap 5 word) : Prop :=
    getr rg 11 = Z_to_bv 64 fD /\ getr rg 12 = Z_to_bv 64 lD /\ getr rg 13 = Z_to_bv 64 (p2 + n - 1) /\ getr rg 14 = Z_to_bv 64 (Z.lor u1 u0)
    /\ getr rg 20 = Z_to_bv 64 p1 /\ getr rg 18 = Z_to_bv 64 p2 /\ getr rg 9 = Z_to_bv 64 n /\ getr rg 21 = Z_to_bv 64 0x1529a0 /\ getr rg 19 = ra /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 2 = Z_to_bv 64 (s - 2192).
  Lemma cWqa_run : forall M regs w0 w1,
    cW_pre regs -> out_agree M -> (0 < n <= 64)%Z ->
    rdn ASEGS M (Z_to_bv 64 faD) 8%nat = Some w0 -> rdn ASEGS M (Z_to_bv 64 laD) 8%nat = Some w1 ->
    (0 <= bytes_le_to_Z w0 < 2 ^ 64)%Z -> (0 <= bytes_le_to_Z w1 < 2 ^ 64)%Z ->
    exists regs',
      msteps ASEGS (mkst regs (0x6cc88 : word) M rom) (mkst regs' (0x6ccd0 : word) M rom)
