  (* [comment removed for export] *)
  Definition qlW_inv (rg : bvmap 5 word) (i : Z) : Prop :=
    getr rg 11 = Z_to_bv 64 (fD + i) /\ getr rg 12 = Z_to_bv 64 lD /\ getr rg 13 = Z_to_bv 64 0 /\ getr rg 20 = Z_to_bv 64 p1 /\ getr rg 18 = Z_to_bv 64 p2 /\ getr rg 9 = Z_to_bv 64 n /\ getr rg 21 = Z_to_bv 64 0x1529a0 /\ getr rg 19 = ra /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 2 = Z_to_bv 64 (s - 2192).
  Definition qlW_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S@0|21;!1,20!1,2|600;!1+12!1,4|35;!1,4|44;!1,4|42;|31;!1,47|45;!1,49!1,4|43;|30;!1,4<|10;!1,4>$rg;R!2'_J13!2+A!3+<3!2'_L#1!3,314vv,6!2'714!2'=2,C!2+A!3+<3!2'_L#1!3,315vv,6!2'715!2'=2/p1;!2+A!3+<3!2'_L#1!3,316vv,6!2'716!2'=2/p2;!2+A!3+<3!2'_L#1!3,318vv,6!2'718!2'=2/n;!2+A!3+<3!2'_L#1!3,31:vv,6!2'71:!2'=2!1,4|D529a0;!2+A!3+<3!2'_L#1!3,31;vv,6!2'71;/ra;!2+A!3+<3!2'_L#1!3,31=vv,6!2'71=!2'=2/s;!3+<3!2'_L#1!3,31?vv,6!2'71?!2'=2!2'H/s;!1,4|;090;").
  Lemma qloopW_run : forall M (q : nat) regs i,
    out_agree M -> (0 < n)%Z -> qlW_inv regs i -> (0 <= i)%Z -> (fD + i + Z.of_nat q + 1 = lD)%Z ->
    exists regs',
      msteps ASEGS (mkst regs (0x6d14c : word) M rom) (mkst regs' (0x6d15c : word) M rom)
